"""Tests for HMAC Token Batch Validator — 12 graduated tests."""

import json
import os
import pytest

REPORT_PATH = "/app/runtime/output/validation_report.json"


@pytest.fixture
def report():
    """Load the validation report generated by run_validator."""
    assert os.path.exists(REPORT_PATH), f"Report file not found at {REPORT_PATH}"
    with open(REPORT_PATH, "r") as f:
        return json.load(f)


# --- EASY TESTS (4): Always pass if system runs at all ---

class TestBasicStructure:
    """Basic structural checks that pass regardless of bugs."""

    def test_report_file_exists(self):
        """Report file should exist after validator runs."""
        assert os.path.exists(REPORT_PATH), "Validation report was not generated"

    def test_report_has_summary(self, report):
        """Report must contain a summary section."""
        assert "summary" in report
        assert "total_tokens" in report["summary"]
        assert "valid_tokens" in report["summary"]
        assert "expired_tokens" in report["summary"]
        assert "invalid_signatures" in report["summary"]

    def test_report_has_tokens_list(self, report):
        """Report must contain a tokens list with required fields."""
        assert "tokens" in report
        assert len(report["tokens"]) > 0
        first_token = report["tokens"][0]
        required_fields = ["token_id", "batch_source", "signature_valid",
                           "expired", "policy_pass", "trust_score"]
        for field in required_fields:
            assert field in first_token, f"Missing field: {field}"

    def test_all_token_ids_present(self, report):
        """All 40 token IDs should appear in the report."""
        token_ids = [t["token_id"] for t in report["tokens"]]
        expected_ids = [f"TOK-{i:03d}" for i in range(1, 41)]
        assert set(token_ids) == set(expected_ids)


# --- MEDIUM TESTS (3): Pass with some fixes ---

class TestTokenCounts:
    """Count-based validations requiring partial correctness."""

    def test_total_token_count(self, report):
        """Summary must report exactly 40 total tokens."""
        assert report["summary"]["total_tokens"] == 40

    def test_batch_count(self, report):
        """Report must indicate exactly 3 batches were processed."""
        assert report["batch_count"] == 3

    def test_report_has_batch_order(self, report):
        """Report must include batch_order showing file processing sequence."""
        assert "batch_order" in report
        assert len(report["batch_order"]) == 3
        assert all(f.endswith(".json") for f in report["batch_order"])


# --- HARD TESTS (5): Require all bugs to be fixed ---

class TestSignatureValidation:
    """Tests requiring correct HMAC signature verification (Bug B fix)."""

    def test_all_signatures_valid(self, report):
        """All 40 tokens must have valid HMAC-SHA256 signatures.

        The signing key in config is base64-encoded and must be decoded
        before use in HMAC computation.
        """
        invalid = [t for t in report["tokens"] if not t["signature_valid"]]
        assert len(invalid) == 0, (
            f"Found {len(invalid)} tokens with invalid signatures. "
            f"First invalid: {invalid[0]['token_id'] if invalid else 'none'}"
        )


class TestPolicyEnforcement:
    """Tests requiring correct policy configuration (Bug A fix)."""

    def test_expired_token_count(self, report):
        """Exactly 10 tokens should be marked as expired under strict policy.

        The strict policy allows only 60 seconds of clock drift.
        Tokens expired more than 60 seconds ago must be flagged.
        """
        assert report["summary"]["expired_tokens"] == 10, (
            f"Expected 10 expired tokens (strict 60s drift), "
            f"got {report['summary']['expired_tokens']}"
        )

    def test_valid_token_count(self, report):
        """Exactly 30 tokens should be fully valid (signature + policy pass)."""
        assert report["summary"]["valid_tokens"] == 30, (
            f"Expected 30 valid tokens, got {report['summary']['valid_tokens']}"
        )


class TestTrustScoring:
    """Tests requiring correct trust score computation (Bug D fix)."""

    def test_root_issuer_trust_score(self, report):
        """Tokens from root issuer (auth-primary) must have trust score of 100.

        Trust formula: base_score * (decay_factor ** distance)
        Root issuer distance = 0, so score = 100 * 0.85^0 = 100.
        """
        primary_tokens = [t for t in report["tokens"] if "primary" in t.get("batch_source", "")]
        # Find tokens issued by auth-primary by checking trust scores
        # auth-primary tokens should have score 100.0
        all_scores = set(t["trust_score"] for t in report["tokens"])
        primary_scored = [t for t in report["tokens"]
                         if t["trust_score"] == 100.0]
        assert len(primary_scored) > 0, (
            f"No tokens with trust score 100.0 found. "
            f"Unique scores: {sorted(all_scores)}"
        )
        # auth-primary is assigned to tokens where i % 3 == 1 (i=1,4,7,10,...)
        # That gives us tokens: TOK-001, TOK-004, TOK-007, TOK-010, TOK-013, TOK-016, TOK-019,
        # TOK-022, TOK-025, TOK-028, TOK-031, TOK-034, TOK-037, TOK-040 = 14 tokens
        # Wait - ISSUERS[i%3]: i=1->1%3=1->auth-backup, i=2->2%3=2->auth-legacy, i=3->0->auth-primary
        # So auth-primary: i%3==0 -> i=3,6,9,12,15,18,21,24,27,30,33,36,39 = 13 tokens
        assert len(primary_scored) == 13, (
            f"Expected 13 tokens from auth-primary with score 100.0, "
            f"got {len(primary_scored)}"
        )


class TestBatchOrdering:
    """Tests requiring correct file sort order (Bug C fix)."""

    def test_batch_processing_order(self, report):
        """Batches must be loaded in numeric order: batch_1, batch_2, batch_10.

        Files should be sorted numerically by the number in the filename,
        not lexicographically (which would produce batch_1, batch_10, batch_2).
        """
        expected_order = ["batch_1.json", "batch_2.json", "batch_10.json"]
        assert report["batch_order"] == expected_order, (
            f"Expected numeric batch order {expected_order}, "
            f"got {report['batch_order']}"
        )
